(function(){
 'use strict';
 const groups=[['all','전체 항목','wallet'],['ceremony','예식 · 본식','hall'],['style','촬영 · 스타일','camera'],['people','가족 · 모임','dining'],['travel','신혼여행','essentials'],['gifts','예물 · 답례','heart']];
 const categories=[
  {id:'venue',group:'ceremony',title:'웨딩홀',icon:'hall',desc:'공간을 빌리는 비용과 하객 식사',items:['대관료','식대']},
  {id:'ceremony',group:'ceremony',title:'결혼식',icon:'flower',desc:'예식 진행, 연출과 하객 이동',items:['본식 부케','본식 헬퍼비','사회자','식전 · 식중 영상','플라워 디렉팅','포토테이블 액자','포토부스','2부 의상','웨딩카','하객 버스 대절 · 음식','하객 숙박','하객 항공권','결혼식 뒤풀이']},
  {id:'main-photo',group:'ceremony',title:'본식 스냅 · 영상',icon:'camera',desc:'결혼식 당일의 사진과 영상 기록',items:['본식 스냅','본식 영상','아이폰 스냅']},
  {id:'styling',group:'style',title:'드레스 · 메이크업 · 예복',icon:'color',desc:'스드메 계약과 별도로 확인할 추가 비용',items:['드레스 · 본식 메이크업','드레스 추가금','드레스 투어 피팅비','본식 메이크업 얼리스타트','예복 · 구두 · 타이 대여','웨딩슈즈','헤어변형']},
  {id:'shoot',group:'style',title:'스냅 촬영',icon:'camera',desc:'촬영부터 의상, 보정과 앨범까지',items:['스튜디오 스냅','야외 스냅','해외 스냅','촬영 의상','촬영 메이크업 · 화장품','촬영 부케','촬영 기타 비용 · 간식','사진 보정','앨범']},
  {id:'care',group:'style',title:'관리 비용',icon:'spark',desc:'두 사람의 촬영 · 본식 전 관리',items:['신랑 · 신부 건강 · 피부 관리','웨딩네일 · 촬영 및 본식','헤어 염색 · 커트']},
  {id:'family',group:'people',title:'가족 · 혼주',icon:'home',desc:'혼주와 직계가족 의상 및 메이크업',items:['혼주 한복','혼주 양복','혼주 · 직계가족 메이크업']},
  {id:'meeting',group:'people',title:'상견례',icon:'dining',desc:'양가가 함께하는 식사와 선물',items:['상견례 식사','상견례 선물']},
  {id:'invitation',group:'people',title:'청첩장 · 모임',icon:'dining',desc:'초대장을 준비하고 소식을 전하는 비용',items:['종이 청첩장 · 식권','모바일 청첩장','청첩장 모임']},
  {id:'reception',group:'people',title:'별도 피로연',icon:'dining',desc:'별도 행사를 진행할 때 확인할 비용',items:['피로연 메이크업','피로연 항공권']},
  {id:'honeymoon',group:'travel',title:'신혼여행',icon:'essentials',desc:'항공부터 숙박, 현지 경비와 준비물까지',items:['항공권','숙소','현지 경비','여행 준비물']},
  {id:'rings',group:'gifts',title:'예물 · 예단',icon:'heart',desc:'두 사람의 약속을 위한 준비',items:['웨딩링']},
  {id:'gifts',group:'gifts',title:'선물 · 답례',icon:'bookmark',desc:'함께해 준 분들에게 전하는 마음',items:['결혼 도우미 선물 · 축가·축사·사회 등','답례품']}
 ];

 const extras={
 venue:[['생화 · 꽃 장식 업그레이드','기본 꽃 장식 범위와 추가 연출 비용'],['식음료 · 주류 추가','식대 포함 범위와 별도 음료 비용'],['보증 인원 초과 식대','계약 식대에 반영했다면 별도로 더하지 않기'],['예식 시간 연장 · 추가 대관','준비·철수 시간을 포함한 이용 범위'],['주차 · 발렛 추가','무료 주차 시간과 차량 지원 범위']],
 'main-photo':[['촬영 시간 연장','기본 촬영 시간과 추가 시간 단위'],['작가 · 카메라 추가','기본 인원·카메라 수 확인'],['원본 · 보정본 추가 구매','제공 컷 수와 원본 포함 여부'],['출장 · 교통비','촬영 지역별 별도 비용']],
 styling:[['드레스 추가금','등급 변경·프리미엄 드레스 선택'],['드레스 투어 피팅비','투어 횟수와 피팅 비용'],['본식 메이크업 얼리스타트','이른 예약 시간의 추가 비용'],['헤어변형','횟수·출장·시간 포함 범위'],['메이크업 담당자 지정','직급·담당자 변경 비용'],['헤어피스 · 가발 · 액세서리','대여·구매·반납 조건'],['드레스 수선 · 배송','수선·왕복 배송 포함 여부']],
 shoot:[['촬영 헬퍼비 · 연장','기본 시간·야외 이동·연장 비용'],['원본 파일 구매','촬영 계약의 원본 제공 범위'],['추가 보정 · 앨범 페이지','기본 보정 컷·페이지 수'],['액자 업그레이드','크기·소재 변경 비용'],['야간 · 주말 · 장소 이용료','촬영 시간과 장소별 비용'],['촬영 의상 추가 · 출장비','벌 수·장소 이동·교통비']],
 family:[['혼주 의상 대여 연장 · 수선','대여 기간·수선·반납 배송'],['혼주 메이크업 얼리스타트 · 출장','인원·예약 시간·출장 범위']],
 invitation:[['청첩장 추가 인쇄 · 배송','수량 변경·봉투·봉인 스티커']],
 honeymoon:[['수하물 · 좌석 · 이동 비용','항공·숙박 기본 요금에 포함된 범위'],['숙박 현지 추가 요금','예약 시 별도로 안내된 현지 결제 비용']]
 };
 const KEY='viewdding.album.budget.draft.v1', C=BudgetCore;
 let selected='all',tab='manage',loadFailed=false,storageFailed=false;
 let draft={target:null,records:{},added:[]};
 try{const raw=JSON.parse(localStorage.getItem(KEY)||'null');if(raw){draft.target=C.amount(raw.target);if(raw.records&&typeof raw.records==='object')for(const [id,r] of Object.entries(raw.records)){try{draft.records[id]=C.normalize(r)}catch{loadFailed=true}}if(Array.isArray(raw.added))draft.added=raw.added.filter(r=>categories.some(c=>c.id===r.category)&&typeof r.id==='string'&&/^custom-[a-z0-9-]+$/.test(r.id)&&typeof r.title==='string').map(r=>({...r,title:r.title.slice(0,120)}));}}catch{loadFailed=true}
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const won=n=>n===null?'미입력':Number(n).toLocaleString('ko-KR')+'원';
 const rows=c=>c.items.map((title,i)=>({id:c.id+'-'+i,title,extra:extras[c.id]?.some(([t])=>t===title)||false})).concat(draft.added.filter(r=>r.category===c.id));
 const allRows=()=>categories.flatMap(rows);
 const rec=id=>draft.records[id]||{};
 const total=()=>C.aggregate(allRows().map(r=>rec(r.id)));
 const visible=()=>categories.filter(c=>selected==='all'||c.group===selected);
 function persist(){try{localStorage.setItem(KEY,JSON.stringify(draft));storageFailed=false;return true}catch{storageFailed=true;return false}}
 function refresh(){const y=window.scrollY,x=window.scrollX,open=[...document.querySelectorAll('.b-category[open]')].map(e=>e.dataset.bCategory),openRows=[...document.querySelectorAll('.b-row[open]')].map(e=>e.dataset.bRow),rail=document.querySelector('.b-groups'),left=rail?.scrollLeft||0;render();for(const el of document.querySelectorAll('.b-category'))el.open=open.includes(el.dataset.bCategory);for(const el of document.querySelectorAll('.b-row'))el.open=openRows.includes(el.dataset.bRow);const next=document.querySelector('.b-groups');if(next)next.scrollLeft=left;window.scrollTo({top:y,left:x,behavior:'instant'})}
 function summary(){const t=total(),margin=draft.target===null?null:draft.target-t.forecast;return `<section class="b-summary b-dashboard" aria-label="전체 예산 요약"><div><span>목표 예산</span><form data-b-target><label class="sr-only" for="b-target">목표 예산 (원)</label><input id="b-target" name="target" inputmode="numeric" placeholder="금액 입력" value="${draft.target??''}"><button type="submit">적용</button></form><small>모든 금액은 원 단위</small></div>${[['총 예상 비용',t.forecast,'계약 총액 우선 · 미계약은 예상 비용'],['계약 총액',t.contract,'예약금·중도금·잔금을 포함한 총액'],['결제 완료',t.paid,'결제 완료로 표시한 금액'],['남은 결제',t.remaining,'계약 총액 − 결제 완료'],[margin!==null&&margin<0?'목표 예산 초과':'예산 여유',margin===null?null:Math.abs(margin),'목표 예산과 총 예상 비용의 차이']].map(([title,n,note])=>`<div><span>${title}</span><strong>${won(n)}</strong><small>${note}</small></div>`).join('')}</section><p class="b-total-note">금액 입력 ${t.known}개 · 계약 전 예상 비용 ${t.uncontracted}개 포함 <span>선택한 분야와 관계없이 전체 합계입니다.</span></p>`}
 function field(name,label,value='',type='text'){return `<label>${label}<input name="${name}" ${type==='money'?'inputmode="numeric" placeholder="미입력"':`type="${type}"`} value="${esc(value??'')}" ${name==='vendor'?'maxlength="120"':''}></label>`}
 function editor(row){const r=rec(row.id),t=C.totals(r);return `<form class="b-edit-form" data-b-record="${row.id}"><div class="b-fields">${field('vendor','업체명',r.vendor)}<label>합계 반영<select name="mode">${[['separate','별도 비용으로 반영'],['included','다른 항목 · 패키지에 포함'],['unused','진행하지 않는 항목']].map(([v,n])=>`<option value="${v}" ${r.mode===v?'selected':''}>${n}</option>`).join('')}</select></label>${field('estimate','예상 비용 (원)',r.estimate,'money')}${field('contract','계약 총액 (원)',r.contract,'money')}</div><p class="b-help">입력 후 ‘입력 반영’을 누르면 전체 합계에 적용됩니다. 계약 총액에는 아래 예약금·중도금·잔금이 모두 포함됩니다. 추가금이 계약 총액에 이미 들어 있다면 해당 추가금은 ‘패키지에 포함’으로 표시하세요.</p><div class="b-payments">${[['deposit','예약금 · 계약금'],['interim','중도금'],['balance','잔금']].map(([k,title])=>`<fieldset><legend>${title}</legend>${k==='balance'?`<span class="b-calculated-label">자동 계산</span><output data-b-balance>${won(t.balance)}</output>`:field(k,'금액 (원)',r[k],'money')}${field(k+'Date','결제 예정일',r[k+'Date'],'date')}<label class="b-check"><input type="checkbox" name="${k}Paid" ${r[k+'Paid']?'checked':''}>결제 완료</label></fieldset>`).join('')}</div><div class="b-edit-bottom"><label>비고<textarea name="note" rows="2" maxlength="1000" placeholder="포함 사항, 추가금 조건, 결제 관련 메모">${esc(r.note)}</textarea></label><div><p data-b-preview>결제 완료 ${won(t.paid)} · 남은 결제 ${won(t.remaining)}</p><p class="b-form-error" role="alert"></p><button type="submit" class="solid-button">입력 반영</button></div></div></form>`}
 function rowHTML(row){const r=rec(row.id),t=C.totals(r),excluded=r.mode==='included'||r.mode==='unused';return `<details class="b-row" data-b-row="${row.id}"><summary><span class="b-row-title">${esc(row.title)} ${row.extra?'<em>추가금</em>':''}<small>${esc(r.vendor||'업체·금액·결제 일정 입력')}${r.note?' · 비고 있음':''}</small></span><span class="b-row-money">${excluded?(r.mode==='included'?'패키지 포함':'진행 안 함'):t.known?won(t.forecast):'금액 미입력'}<small>${excluded?'합계 제외':t.known?'결제 '+won(t.paid):'눌러서 입력'}</small></span><span aria-hidden="true">＋</span></summary>${editor(row)}</details>`}
 function category(c,i){const list=rows(c),t=C.aggregate(list.map(r=>rec(r.id)));return `<details class="b-category" data-b-category="${c.id}" ${i===0?'open':''}><summary><span class="b-category-icon">${icon(c.icon)}</span><span class="b-category-title"><strong>${c.title}</strong><small>${list.length}개 항목 · ${c.desc}</small></span><span class="b-category-sum">${t.known?won(t.forecast):'미입력'}</span><span class="b-chevron">${icon('plus')}</span></summary><div class="b-category-body">${list.map(rowHTML).join('')}<form class="b-add-form" data-b-add="${c.id}"><label class="sr-only" for="add-${c.id}">${c.title} 새 항목명</label><input id="add-${c.id}" name="title" maxlength="120" required placeholder="직접 항목 추가"><button type="submit">${icon('plus')} 추가</button></form></div></details>`}
 function extraGuide(){return `<div class="b-guide-intro"><h2>견적서에서 한 번 더 확인해요</h2><p>업체와 계약에 따라 달라지는 확인용 항목입니다. 기본 금액에 포함되어 있는지 먼저 확인하고 필요한 비용만 추가하세요.</p></div>${visible().filter(c=>extras[c.id]).map(c=>`<section class="b-extra-category"><h3>${icon(c.icon)}${c.title}</h3>${extras[c.id].map(([title,note],i)=>{const existing=rows(c).some(r=>r.title===title);return `<div class="b-extra-row"><span><strong>${title}</strong><small>${note}</small></span><button data-b-extra="${c.id}:${i}" ${existing?'disabled':''}>${existing?'예산에 있음':'+ 예산에 추가'}</button></div>`}).join('')}</section>`).join('')||'<p class="b-empty">이 분야에는 별도 추가금 안내가 없어요. 예산 관리에서 필요한 항목을 직접 추가할 수 있습니다.</p>'}`}
 function renderBudget(){return `${heading('','결혼 예산','기본 비용부터 추가금, 남은 결제까지 한곳에서 관리하세요.')}<p class="b-storage-note" role="status">${storageFailed?'임시 저장에 실패했어요. 입력값은 현재 화면에만 남아 있어요.':loadFailed?'이전 임시 기록 일부를 읽지 못했어요. 입력값을 확인해주세요.':'입력 내용은 이 브라우저에 임시 저장됩니다. 다른 기기와 동기화되지 않아요.'}</p>${summary()}<div class="b-tabs" aria-label="예산 화면"><button data-b-tab="manage" aria-pressed="${tab==='manage'}">${icon('wallet')}예산 관리</button><button data-b-tab="extras" aria-pressed="${tab==='extras'}">${icon('plus')}추가금 체크</button></div><div class="b-layout"><nav class="b-groups" aria-label="예산 분야">${groups.map(([id,title,ic])=>`<button id="budget-group-${id}" data-budget-group="${id}" aria-pressed="${selected===id}">${icon(ic)}<span>${title}</span></button>`).join('')}</nav><section class="b-content" aria-label="예산 세부 항목">${tab==='extras'?extraGuide():`<header class="b-list-header"><div><h2>${groups.find(([id])=>id===selected)[1]}</h2><p>항목을 눌러 금액과 결제 일정을 입력하세요.</p></div><span>단위: 원</span></header>${visible().map(category).join('')}`}</section></div>`}
 function homeMetric(){const t=total();return `<span class="metric-label">총 예상 비용</span><span class="metric-value">${t.known?Number(t.forecast/10000).toLocaleString('ko-KR',{maximumFractionDigits:1})+'<small>만원</small>':'미입력'}</span><span class="metric-note">${t.known?'남은 결제 '+won(t.remaining):'예산과 결제 일정 입력하기'}</span>`}
 function homeCard(){const t=total();return `<div class="budget-card b-home-card"><div class="budget-top"><span>우리의 결혼 예산</span><span>브라우저 임시 기록</span></div><h3>${t.known?won(t.forecast):'예산을 기록해보세요.'}</h3><p>결제 완료 ${won(t.paid)} · 남은 결제 ${won(t.remaining)}</p><a class="text-button" href="#budget">예산 관리하기 ${icon('arrow')}</a></div>`}
 function formRecord(form){const f=new FormData(form),raw={};for(const k of ['estimate','contract','deposit','interim','vendor','note','mode','depositDate','interimDate','balanceDate'])raw[k]=f.get(k);for(const k of ['depositPaid','interimPaid','balancePaid'])raw[k]=f.get(k)==='on';return C.normalize(raw)}
 function updatePreview(form){const error=form.querySelector('.b-form-error');try{const t=C.totals(formRecord(form));form.querySelector('[data-b-balance]').textContent=won(t.balance);form.querySelector('[data-b-preview]').textContent='결제 완료 '+won(t.paid)+' · 남은 결제 '+won(t.remaining);error.textContent='';return true}catch(e){error.textContent=e.message;form.querySelector('[data-b-balance]').textContent='확인 필요';return false}}
 // Keep text, focus, expanded sections and scroll stable while editing.
 document.addEventListener('input',e=>{const f=e.target.closest?.('[data-b-record]');if(f)updatePreview(f)});
 document.addEventListener('submit',e=>{const f=e.target;
 if(f.matches?.('[data-b-record]')){e.preventDefault();if(!updatePreview(f))return;draft.records[f.dataset.bRecord]=formRecord(f);const saved=persist();const id=f.dataset.bRecord;refresh();const row=document.querySelector(`[data-b-row="${id}"]`);if(row){row.open=true;row.querySelector('button[type=submit]')?.focus({preventScroll:true})}toast(saved?'입력 내용을 반영했어요.':'이 브라우저에 임시 저장할 수 없어요.');}
 else if(f.matches?.('[data-b-target]')){e.preventDefault();try{draft.target=C.amount(new FormData(f).get('target'));persist();refresh();document.getElementById('b-target')?.focus({preventScroll:true})}catch(err){toast(err.message)}}
 else if(f.matches?.('[data-b-add]')){e.preventDefault();const title=String(new FormData(f).get('title')||'').trim().slice(0,120);if(!title)return;draft.added.push({id:'custom-'+crypto.randomUUID(),category:f.dataset.bAdd,title,extra:false});persist();refresh();toast('항목을 추가했어요.');}
 });
 document.addEventListener('click',e=>{const el=e.target.closest('[data-budget-group],[data-b-tab],[data-b-extra]');if(!el)return;
 if(el.dataset.bExtra){const [id,i]=el.dataset.bExtra.split(':'),title=extras[id]?.[i]?.[0];if(!title||rows(categories.find(c=>c.id===id)).some(r=>r.title===title))return;draft.added.push({id:'custom-'+crypto.randomUUID(),category:id,title,extra:true});persist();refresh();toast('예산에 추가했어요. 예산 관리에서 금액을 입력하세요.');}
 else if(el.dataset.bTab){tab=el.dataset.bTab;refresh();document.querySelector(`[data-b-tab="${tab}"]`)?.focus({preventScroll:true});}
 else{selected=el.dataset.budgetGroup;refresh();document.querySelector('.b-category')?.setAttribute('open','');document.getElementById('budget-group-'+selected)?.focus({preventScroll:true})}
 });
 window.WeddingBudget={render:renderBudget,homeCard,homeMetric,categories};
})();
